settings.custom_js:
setTimeout(() => {
const signOutstatus = document.querySelector('.iconuser img');
  if (!signOutstatus && !sessionStorage.getItem('showedpopup')) {
    const header = document.querySelector('header');
    header.insertAdjacentHTML(
      'beforebegin',
      `<div class="popupcontainer" role="dialog" aria-labelledby="popupHeading" aria-describedby="popupText">
        <a id="closepopup" href="#" aria-label="Close popup">x</a>
        <div class="popuptext">Create an account to get personalized recommendations!</div>
      </div>`
    );

    const popupContainer = document.querySelector('.popupcontainer');

    const removePopup = () => {
      popupContainer.remove();
      sessionStorage.setItem('showedpopup', 'true');
    };

    ['#closepopup', '.user-icon'].forEach((selector) => {
      const element = document.querySelector(selector);
      if (element) element.addEventListener('click', removePopup);
    });
  }
}, 3000);

setTimeout(() => {
    document.querySelector('#pin-layer-heading-560')?.appendChild(Object.assign(document.createElement('a'), {
        href: '#', className: 'toggleall', textContent: 'Select/Unselect All', ariaLabel: 'Select all',
        onclick: e => {
            e.preventDefault();
            const inputs = [...document.querySelectorAll('.category-item input')];
            const allChecked = inputs.every(i => i.checked);
            const allUnchecked = inputs.every(i => !i.checked);
            inputs.forEach(i => (allChecked || allUnchecked || i.checked) && i.click());
        }
    }));
}, 1000);

