/*pop-up*/
.popupcontainer {
	position: fixed;
  background: var(--secondary);
  right: 60px;
  clip-path: polygon(0 0, 95% 0%, 100% 50%, 95% 100%, 0 100%);
  top: 10px;
  padding: 8px 30px 8px 10px;
  z-index: 999999;
  border-radius: 0px;
 max-width:400px;
  display: flex;
  align-items: center;
  cursor: pointer;
  animation: bounce 2s infinite;
  font-weight: bold;
  color: #fff;
}
.popupcontainer a  {
	padding: 5px;
	margin-left: auto;
	max-width: max-content;
	font-weight: bold;
	font-size: 18px;
	line-height: 1;
	transition: 0.3s;
	display: grid;
	place-content: center;
	border:1px solid var(--primary);
	margin-bottom: 2px;
	margin-right: 5px;
	min-width:30px;
	height:30px;
}
.popupcontainer a:hover {
	color: #fff;
	background: var(--primary);
	border-radius: 100px;
	
}

.popupcontainer:after {
clip-path: polygon(50% 0%, 0% 100%, 100% 100%);
	background: var(--secondary);
	content: '';
	position: absolute;
	right: 15px;
	width: 35px;
	height: 25px;
	top:-20px;
	
}

@keyframes bounce {
    0%, 100% {
      transform: translateX(0);
		
    }
    50% {
      transform: translateX(10px);
	
    }
  }
@media (min-width:768px) {
  .popupcontainer {
  top: 59px;
    clip-path: unset;
    right: 8px;
  
  }
}

.toggleall {
	display: inline-block;
